(function () {
  'use strict';

  var MAX_FILE_BYTES = 8 * 1024 * 1024;
  // The current WebView bridge uses BYTES payloads and assembles received files
  // in memory. Keep a conservative cap until a native FILE-payload stream is
  // implemented; advertising multi-GB support here would risk OOMs and radio
  // stalls on trekking phones.
  var MAX_BRIDGE_FILE_BYTES = 64 * 1024 * 1024;
  var CHUNK_BYTES = 8 * 1024;
  var state = { running: false, demo: false, peers: {}, messages: [], funEvents: [], aiMessages: [], pendingPairings: {}, logs: [], transfers: {}, received: {}, seen: {}, listeners: false, relay: false, recording: null, recorder: null, diagnostic: null, peerTest: null, startError: '', ecoTimer: null };
  var deviceId = localStorage.getItem('rw_mesh_device_id') || id();
  localStorage.setItem('rw_mesh_device_id', deviceId);

  function plugin() { return window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.NearbyMesh; }
  function esc(value) { var d = document.createElement('div'); d.textContent = String(value == null ? '' : value); return d.innerHTML; }
  function id() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }
  function now() { return new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }); }
  function requirePlugin() { var p = plugin(); if (!p) throw new Error('Trail Mesh is available only in the RoamWise Android app.'); return p; }
  function packet(type, data) { var p={ rw: 1, type: type, id: id(), origin: deviceId, ttl: state.relay ? 3 : 0, at: Date.now(), data: data || {} }; state.seen[p.id]=p.at; return JSON.stringify(p); }
  function sendPacket(type, data, endpointId) { if(state.demo)return simulatePacket(type,data);return requirePlugin().sendMessage({ message: packet(type, data), endpointId: endpointId || null }); }
  function simulatePacket(type,data){return new Promise(function(resolve){setTimeout(function(){if(type==='chat')state.messages.push({mine:false,from:'Nanda · Demo trekker',text:'Received offline: “'+String(data.text||'').slice(0,80)+'”',time:now()});else if(type==='team')state.messages.push({mine:false,from:'Nanda · Demo trekker',text:data.action==='radio-check'?'SAFE · demo reply from the rear marker':'Acknowledged: '+data.text,time:now()});else if(type==='fun'){state.messages.push({mine:false,from:'Nanda · Demo trekker',text:'Challenge accepted! (simulated reply)',time:now()});state.funEvents.push({ok:true,text:'Nanda accepted · simulated reply',time:now()});}else if(type==='lost')state.messages.push({mine:false,from:'Nanda · Demo trekker',text:'Lost-trekker alert received (simulation only)',time:now()});else if(type==='sos')state.messages.push({mine:false,from:'Nanda · Demo trekker',text:'SOS acknowledged in demo mode — no real alert was transmitted',time:now()});render();resolve({simulated:true});},450);});}
  function relayPacket(p, sourceEndpoint) { if(!state.relay || !p.ttl || p.ttl<1 || p.origin===deviceId || /^(file-|ping$|pong$)/.test(p.type)) return; var relayed=JSON.stringify(Object.assign({},p,{ttl:p.ttl-1})); Object.keys(state.peers).forEach(function(key){if(key!==sourceEndpoint&&state.peers[key].connected)requirePlugin().sendMessage({message:relayed,endpointId:key}).catch(function(){});}); }
  function toast(message) { if (typeof window.showToast === 'function') window.showToast(message); else alert(message); }
  function formatBytes(n) { return n < 1024 * 1024 ? Math.ceil(n / 1024) + ' KB' : (n / 1024 / 1024).toFixed(1) + ' MB'; }
  function peerCount() { return Object.keys(state.peers).filter(function (key) { return state.peers[key].connected; }).length; }
  function safeName() { return (localStorage.getItem('rw_mesh_name') || localStorage.getItem('rw_user_name') || 'RoamWise trekker').slice(0, 32); }
  function trace(level,step,message){var row={at:now(),level:level||'info',step:step||'Trail Mesh',message:String(message||'')};state.logs.push(row);if(state.logs.length>80)state.logs.shift();try{localStorage.setItem('rw_mesh_health_log',JSON.stringify(state.logs.slice(-40)));}catch(_){}renderConsole();}
  function loadTrace(){try{var rows=JSON.parse(localStorage.getItem('rw_mesh_health_log')||'[]');if(Array.isArray(rows))state.logs=rows.slice(-40);}catch(_){} }
  function nextStep(){if(state.demo)return'Demo is active. Stop it before testing real radios.';if(state.startError)return /8034|COARSE_LOCATION/i.test(state.startError)?'On Android 12 or older, allow the legacy location permission; on Android 13+, install the latest build and retry with Nearby/Bluetooth/Wi-Fi enabled.':'Open the latest error below, follow its action, then retry.';if(!state.running)return'Tap Allow & start. For a UI-only check, choose Try with demo trekker.';if(!peerCount())return'Running correctly. Start Trail Mesh on a second phone and compare verification digits.';return'Connected. Run Test with teammate, then exercise Chat, Team, Fun and Share.';}
  function cue(kind) { if (localStorage.getItem('rw_audio_enabled')==='0') return; try { var C=window.AudioContext||window.webkitAudioContext;if(!C)return;var c=new C(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.value=kind==='alert'?740:kind==='success'?520:330;g.gain.setValueAtTime(.0001,c.currentTime);g.gain.exponentialRampToValueAtTime(kind==='alert'?.11:.045,c.currentTime+.015);g.gain.exponentialRampToValueAtTime(.0001,c.currentTime+(kind==='alert'?.55:.16));o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+(kind==='alert'?.56:.17));o.onended=function(){c.close();}; } catch (_) {} }
  function scene(title,subtitle,icon) { return '<div class="rwm-scene" aria-label="'+esc(title)+'"><div class="rwm-sun"></div><div class="rwm-peak back"></div><div class="rwm-peak front"></div><div class="rwm-path"></div><div class="rwm-scene-copy"><span>'+icon+'</span><div><b>'+esc(title)+'</b><small>'+esc(subtitle)+'</small></div></div></div>'; }

  function styles() {
    if (document.getElementById('rwMeshStyles')) return;
    var s = document.createElement('style'); s.id = 'rwMeshStyles';
    s.textContent = '#rwMeshOverlay{position:fixed;inset:0;background:var(--bg,#07090F);z-index:2147483000;color:var(--t1,#F2EFE6);font-family:inherit;overflow:auto;overscroll-behavior:contain;padding-top:env(safe-area-inset-top);padding-bottom:env(safe-area-inset-bottom)}' +
      '.rwm-shell{max-width:720px;margin:auto;min-height:calc(100dvh - env(safe-area-inset-top) - env(safe-area-inset-bottom));background:radial-gradient(circle at 85% 0,rgba(142,79,255,.13),transparent 38%),var(--bg,#07090F)}.rwm-head{position:sticky;top:0;background:rgba(7,9,15,.94);backdrop-filter:blur(18px);padding:12px 16px;min-height:58px;box-sizing:border-box;display:flex;align-items:center;gap:10px;z-index:4;border-bottom:1px solid var(--b2,#26304C)}' +
      '.rwm-brand{width:36px;height:36px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,var(--gold,#E8BA6C),#A96CFF);box-shadow:0 0 24px rgba(169,108,255,.25)}.rwm-head h2{margin:0;flex:1;font-size:19px;letter-spacing:-.02em}.rwm-close,.rwm-btn{border:1px solid transparent;border-radius:12px;padding:11px 14px;font:700 13px/1 inherit;background:linear-gradient(135deg,var(--gold,#E8BA6C),var(--gold2,#C8913E));color:#08090F;min-height:42px}.rwm-close{width:42px;padding:0;font-size:20px}.rwm-btn.secondary{background:var(--bg2,#12151F);border-color:var(--b2,#26304C);color:var(--t1,#F2EFE6)}.rwm-btn.danger{background:linear-gradient(135deg,#FF746A,#C4302B);color:#fff}' +
      '.rwm-tabs{display:flex;overflow-x:auto;scrollbar-width:none;padding:10px 14px;gap:7px;background:rgba(7,9,15,.96);position:sticky;top:58px;z-index:3;border-bottom:1px solid var(--b2,#26304C)}.rwm-tabs::-webkit-scrollbar{display:none}.rwm-tab{white-space:nowrap;border:1px solid var(--b2,#26304C);border-radius:999px;padding:9px 13px;background:var(--bg2,#12151F);color:var(--t2,#A7ADBD);font:700 12px/1 inherit}.rwm-tab.active{background:linear-gradient(135deg,rgba(232,186,108,.18),rgba(169,108,255,.2));border-color:var(--gold,#E8BA6C);color:var(--gold,#E8BA6C)}' +
      '.rwm-body{padding:14px 14px calc(28px + env(safe-area-inset-bottom))}.rwm-panel{display:none}.rwm-panel.active{display:block}.rwm-card{background:linear-gradient(145deg,rgba(19,26,46,.98),rgba(12,16,30,.98));border:1px solid var(--b2,#26304C);border-radius:20px;padding:16px;margin-bottom:13px;box-shadow:0 16px 42px rgba(0,0,0,.2)}.rwm-card h3{margin:0 0 9px;font-size:17px}.rwm-note{font-size:12.5px;color:var(--t2,#A7ADBD);line-height:1.58}.rwm-note b{color:var(--t1,#F2EFE6)}.rwm-row{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.rwm-input{box-sizing:border-box;width:100%;background:var(--bg,#07090F);border:1px solid var(--b2,#26304C);border-radius:13px;padding:12px;color:var(--t1,#F2EFE6);margin:7px 0;font:inherit}' +
      '.rwm-msg{padding:10px 12px;border-radius:13px;background:var(--bg2,#12151F);border:1px solid var(--b2,#26304C);margin:7px 0}.rwm-msg.mine{background:rgba(232,186,108,.1);border-color:rgba(232,186,108,.35);margin-left:12%}.rwm-meta{font-size:10px;color:var(--t3,#747C91);margin-top:3px}.rwm-badge{font-size:10px;border-radius:999px;padding:5px 8px;background:var(--bg2,#12151F);border:1px solid var(--b2,#26304C)}.rwm-good{color:#4ADE80;border-color:rgba(74,222,128,.35)}.rwm-warn{color:var(--gold,#E8BA6C)}.rwm-sos{border-color:rgba(255,107,107,.55);background:linear-gradient(145deg,rgba(60,19,27,.96),rgba(20,16,28,.98))}.rwm-guide li{margin:8px 0;line-height:1.45}.rwm-progress{height:6px;background:#07090F;border-radius:5px;overflow:hidden}.rwm-progress i{display:block;height:100%;background:linear-gradient(90deg,var(--gold,#E8BA6C),#A96CFF)}' +
      '.rwm-test{display:grid;gap:7px;margin-top:10px}.rwm-check{display:flex;gap:8px;align-items:flex-start;padding:9px 10px;border-radius:11px;background:rgba(255,255,255,.035);font-size:12px}.rwm-check.pass{color:#4ADE80}.rwm-check.fail{color:#FF746A}.rwm-check.wait{color:var(--gold,#E8BA6C)}.rwm-error{display:none;margin-top:10px;padding:12px;border-radius:13px;background:rgba(255,83,83,.1);border:1px solid rgba(255,116,106,.45);color:#FFD4D0}.rwm-error.show{display:block}.rwm-scene{height:132px;position:relative;overflow:hidden;border-radius:20px;margin-bottom:13px;background:linear-gradient(160deg,#20294a 0%,#6b3d89 52%,#e8ba6c 130%);box-shadow:0 18px 46px #0008}.rwm-sun{position:absolute;width:44px;height:44px;border-radius:50%;right:15%;top:18px;background:#ffd487;box-shadow:0 0 30px #ffd48799;animation:rwmBreathe 4s ease-in-out infinite}.rwm-peak{position:absolute;left:-8%;bottom:-2px;width:75%;height:78%;background:#1b2440;clip-path:polygon(0 100%,45% 10%,58% 44%,68% 31%,100% 100%)}.rwm-peak.front{left:37%;width:76%;height:68%;background:#0d1428}.rwm-path{position:absolute;bottom:-20px;left:45%;width:28px;height:90px;background:#d8af6d;transform:perspective(80px) rotateX(28deg);border-radius:50%}.rwm-scene-copy{position:absolute;inset:auto 13px 12px;display:flex;gap:10px;align-items:center;padding:9px 11px;background:#080a12bf;border:1px solid #ffffff22;border-radius:14px;backdrop-filter:blur(9px)}.rwm-scene-copy>span{font-size:24px}.rwm-scene-copy b,.rwm-scene-copy small{display:block}.rwm-scene-copy small{font-size:10px;color:#bdc3d2;margin-top:2px}.rwm-tip{border-left:3px solid var(--gold,#E8BA6C);padding-left:10px}.rwm-choice{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}.rwm-choice .rwm-btn{min-height:54px}#rwMeshFab{position:fixed;right:14px;bottom:calc(108px + env(safe-area-inset-bottom));z-index:99999;width:48px;height:48px;border:1px solid rgba(232,186,108,.5);border-radius:16px;background:linear-gradient(135deg,#171D31,#2A1740);color:var(--gold,#E8BA6C);font-size:21px;box-shadow:0 12px 30px #0009}#rwMeshOverlay:not([style*="display: none"])~#rwMeshFab{display:none}.rwm-alarm{animation:rwmPulse .7s infinite alternate}@keyframes rwmPulse{to{background:#f00}}@keyframes rwmBreathe{50%{transform:scale(1.1);opacity:.82}}@media(prefers-reduced-motion:reduce){.rwm-sun,.rwm-alarm{animation:none}}@media(max-width:420px){.rwm-head{padding-left:12px;padding-right:12px}.rwm-body{padding-left:10px;padding-right:10px}.rwm-btn{flex:1}.rwm-tabs{padding-left:10px}}';
    s.textContent += '.rwm-console{font:11px/1.45 ui-monospace,SFMono-Regular,monospace;max-height:290px;overflow:auto;background:#05070d;border:1px solid var(--b2,#26304C);border-radius:13px;padding:9px}.rwm-log{padding:7px;border-bottom:1px solid #ffffff12;overflow-wrap:anywhere}.rwm-log.error{color:#ff8b83}.rwm-log.ok{color:#55df8b}.rwm-next{padding:12px;border-radius:13px;background:rgba(232,186,108,.1);border:1px solid rgba(232,186,108,.35);color:var(--gold,#E8BA6C)}.rwm-character{width:64px;height:64px;border-radius:22px;display:grid;place-items:center;font-size:34px;background:linear-gradient(135deg,#e8ba6c,#a96cff);box-shadow:0 10px 28px #0008;margin-bottom:10px;animation:rwmBreathe 4s ease-in-out infinite}.rwm-radar{height:150px;width:150px;border:1px solid rgba(232,186,108,.7);border-radius:50%;margin:8px auto 14px;position:relative;background:radial-gradient(circle,rgba(74,222,128,.2) 0 2px,transparent 3px),repeating-radial-gradient(circle,transparent 0 26px,rgba(232,186,108,.22) 27px 28px),linear-gradient(90deg,transparent 49%,rgba(232,186,108,.22) 50% 51%,transparent 52%),linear-gradient(transparent 49%,rgba(232,186,108,.22) 50% 51%,transparent 52%);overflow:hidden}.rwm-radar:after{content:"";position:absolute;inset:0;background:conic-gradient(from 0deg,transparent 0 78%,rgba(74,222,128,.42) 84%,transparent 90%);animation:rwmSweep 3.2s linear infinite}.rwm-dot{position:absolute;z-index:1;width:10px;height:10px;border-radius:50%;background:#4ade80;box-shadow:0 0 14px #4ade80;transform:translate(-50%,-50%)}@keyframes rwmSweep{to{transform:rotate(360deg)}}';
    document.head.appendChild(s);
  }

  function template() {
    return '<div class="rwm-shell"><div class="rwm-head"><span class="rwm-brand">📡</span><h2>Trail Mesh</h2><span id="rwmStatus" class="rwm-badge">Stopped</span><button class="rwm-close" data-rwm-close aria-label="Close Trail Mesh">✕</button></div>' +
      '<div class="rwm-tabs">' + ['Connect','Chat','Team','SOS','Share','Fun','Guide'].map(function (x, i) { return '<button class="rwm-tab '+(i?'':'active')+'" data-rwm-tab="'+x.toLowerCase()+'">'+x+'</button>'; }).join('') + '</div><div class="rwm-body">' +
      '<section class="rwm-panel active" data-rwm-panel="connect">'+scene('Your offline trail lifeline','Nearby phones · no internet required','🏔️')+'<div class="rwm-card"><h3>Before Trail Mesh starts</h3><p class="rwm-note"><b>RoamWise uses Nearby Devices access (Bluetooth and nearby Wi-Fi) to discover and communicate with verified RoamWise phones near you.</b> On Android 13 and newer, current Google Nearby uses Nearby/Bluetooth/Wi‑Fi permissions without location. Legacy Android versions may request location for discovery; RoamWise does not store or upload that compatibility permission. Your chosen trail name is visible nearby and text and alerts transfer device-to-device. Microphone, precise location and selected-file access occur only when you separately choose a voice note, location-assisted SOS or file share.</p><p class="rwm-note">Internet and mobile service are not required, but devices must remain within local radio range. Trail Mesh is not satellite rescue and does not replace emergency services.</p><input id="rwmName" class="rwm-input" maxlength="32" placeholder="Trail display name"><label class="rwm-note"><input id="rwmEco" type="checkbox" checked> Battery guard: stop automatically after 2 hours (recommended)</label><div class="rwm-row"><button id="rwmStart" class="rwm-btn">Allow & start</button><button id="rwmStop" class="rwm-btn secondary">Stop</button><button id="rwmPing" class="rwm-btn secondary">Test network</button></div><div id="rwmStartError" class="rwm-error" role="alert"></div></div><div class="rwm-card"><h3>Multi-hop relay (experimental)</h3><label><input id="rwmRelay" type="checkbox"> Relay text, team, lost-trekker and SOS alerts through verified phones</label><p class="rwm-note">Opt-in on each phone. Maximum three hops; duplicate IDs and expiry prevent loops. Files, songs, videos and voice notes are never relayed because they can congest an emergency network. Relay confirms forwarding—not rescue delivery.</p></div><div class="rwm-card"><h3>Nearby trekkers <span id="rwmPeerCount" class="rwm-badge">0</span></h3><div id="rwmPeers" class="rwm-note">No connected trekkers yet.</div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="chat"><div class="rwm-card"><h3>Offline Trip Chat & radio room</h3><p class="rwm-note">Messages are shared with verified connected devices and can appear in Trip Chat. Voice is push-to-talk: record, release and share. This remains usable under weak links where live conferencing would break.</p><div id="rwmMessages"></div><textarea id="rwmChatInput" class="rwm-input" rows="2" maxlength="4000" placeholder="Message your nearby team"></textarea><div class="rwm-row"><button id="rwmSend" class="rwm-btn">Send offline</button><button id="rwmVoice" class="rwm-btn secondary">🎙 Record radio note</button><button id="rwmRadioCheck" class="rwm-btn secondary">Radio check</button><button id="rwmClearChat" class="rwm-btn secondary">Clear old chat</button></div><p class="rwm-note rwm-tip">For a call-like exchange, use short radio notes. Continuous full-duplex calling is not promised over a battery-saving mesh radio.</p></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="team"><div class="rwm-card"><h3>Trek leader coordination</h3><input id="rwmCheckpoint" class="rwm-input" maxlength="120" placeholder="Checkpoint or meeting place"><div class="rwm-row"><button class="rwm-btn" data-rwm-team="rollcall">Roll call</button><button class="rwm-btn secondary" data-rwm-team="regroup">Regroup</button><button class="rwm-btn secondary" data-rwm-team="hold">Hold position</button></div></div><div class="rwm-card"><h3>Find a lost trekker</h3><p class="rwm-note">Broadcasts an alert locally. The missing person becomes discoverable only when their phone is running Trail Mesh and enters radio range.</p><input id="rwmLostName" class="rwm-input" maxlength="80" placeholder="Name / description"><button id="rwmLost" class="rwm-btn danger">Broadcast lost-trekker alert</button></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="sos"><div class="rwm-card rwm-sos"><h3>Emergency help</h3><p class="rwm-note">If mobile service exists, contact local emergency services first. Trail Mesh only alerts nearby connected users and delivery is not guaranteed.</p><select id="rwmSosType" class="rwm-input"><option>Medical emergency</option><option>Lost / separated</option><option>Unsafe situation</option><option>Need supplies or assistance</option></select><input id="rwmSosDetails" class="rwm-input" maxlength="240" placeholder="Details, clothing, direction, injury"><label class="rwm-note"><input id="rwmSosLocation" type="checkbox"> Attach precise location (optional; requested only if checked)</label><div class="rwm-row"><button id="rwmSOS" class="rwm-btn danger">Broadcast nearby SOS</button><button id="rwmAlarm" class="rwm-btn secondary">Sound local alarm</button><button id="rwmOfficialSOS" class="rwm-btn secondary">Open RoamWise SOS</button></div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="share"><div class="rwm-card"><h3>Share without internet</h3><p class="rwm-note">Send selected media directly to a verified teammate. Files above 8 MB show a battery/radio warning; this WebView bridge safely caps a transfer at 64 MB and keeps both screens open until complete.</p><input id="rwmFile" type="file" class="rwm-input" accept="image/*,video/*,audio/*,.pdf,.txt"><button id="rwmShare" class="rwm-btn">Share selected file</button><p class="rwm-note rwm-tip">2–10 GB transfers need a future native FILE-payload stream. They are intentionally not faked here because assembling that much data in a phone WebView can crash the app.</p><div id="rwmTransfers"></div></div></section>' +
      '<section class="rwm-panel" data-rwm-panel="fun">'+scene('Camp mode','Tiny offline games, big trail memories','🔥')+'<div class="rwm-card"><h3>Trail fun</h3><p class="rwm-note">Tap a game to send its challenge. The activity feed confirms whether it was sent, simulated or rejected.</p><div class="rwm-choice"><button class="rwm-btn" data-rwm-fun="photo">📷 Photo challenge</button><button class="rwm-btn secondary" data-rwm-fun="story">🔥 Campfire story</button><button class="rwm-btn secondary" data-rwm-fun="quiz">🧭 Trail quiz</button><button class="rwm-btn secondary" data-rwm-fun="cheer">🙌 Team cheer</button><button class="rwm-btn secondary" data-rwm-fun="scavenger">🍃 Scavenger hunt</button><button class="rwm-btn secondary" data-rwm-fun="summit">🏁 Summit countdown</button></div><div id="rwmFunFeed" class="rwm-test"><div class="rwm-check wait">○ Choose a challenge to begin</div></div></div><div class="rwm-card"><h3>Talk to a trail character</h3><div id="rwmCharacterPortrait" class="rwm-character" aria-live="polite">🧭</div><p class="rwm-note">Ask a locally available travel character for ideas, stories, packing prompts or morale. Replies are an offline RoamWise companion simulation; do not use them for emergency or medical decisions.</p><select id="rwmCharacter" class="rwm-input"><option value="nanda">Nanda · Uttarakhand guide</option><option value="tenzing">Tenzing · Everest storyteller</option><option value="himachali">Maya · Himachal ranger</option><option value="ladakhi">Tashi · Ladakh navigator</option></select><div id="rwmAiMessages" class="rwm-test"><div class="rwm-check wait">○ Choose a character and say hello</div></div><textarea id="rwmAiInput" class="rwm-input" rows="2" maxlength="500" placeholder="Ask about the trail, camp, food or morale"></textarea><div class="rwm-row"><button id="rwmAiSend" class="rwm-btn">Talk offline</button><button id="rwmAiSpeak" class="rwm-btn secondary">🔊 Read last reply</button><button id="rwmAiClear" class="rwm-btn secondary">Clear chat</button></div></div></section>' +
      '<section class="rwm-panel rwm-guide" data-rwm-panel="guide"><div class="rwm-card"><h3>Quick tutorial</h3><ol><li>Open Trail Mesh on every Android phone and tap <b>Allow & start</b>.</li><li>Keep Bluetooth, Wi-Fi and location services enabled. Android may require Nearby Devices and approximate location permissions.</li><li>When a request arrives, open the <b>Nearby radar</b> card. Compare the same verification digits face to face, then tap <b>Accept matching digits</b>. If you missed the popup, the request remains in that card until it expires.</li><li>If you are coordinating by voice, type the digits into <b>Share digits manually</b> to copy/share them. This is a reminder only; it cannot accept a connection or bypass Android verification.</li><li>Use Offline Trip Chat, Team, Share, Fun, or SOS. Keep phones nearby and the app open during transfers.</li><li>Enable relay only when the group agrees; distribute relay phones along the route.</li><li>Tap Stop when the trek ends to stop discovery and advertising.</li></ol></div><div class="rwm-card"><h3>Safety & privacy</h3><ul><li>Your chosen trail name is visible to nearby Trail Mesh users while running.</li><li>Never accept an unexpected verification request.</li><li>Range varies with terrain, bodies, weather, and hardware. Relay is limited to three hops and lightweight alerts.</li><li>Voice uses recorded push-to-talk notes; it is not a guaranteed full-duplex phone call.</li><li>Large files and continuous calls are intentionally limited to preserve battery and emergency radio capacity.</li><li>Trail Mesh cannot silently install an APK on another phone. Use the Play Store or a user-initiated, trusted Android package installer flow and confirm the source before installing.</li><li>Use official emergency channels whenever available. Do not rely on Trail Mesh as your only safety plan.</li></ul></div><div class="rwm-card"><h3>Ailon Tusk shortcuts</h3><p class="rwm-note">Try: “open Trail Mesh”, “mesh status”, “find lost trekker”, or “nearby SOS”. Tusk opens the matching control while you confirm every safety-sensitive broadcast.</p></div></section></div></div>';
  }

  function decoratePanels(root) {
    if(!root.querySelector('[data-rwm-tab="health"]')){var tab=document.createElement('button');tab.className='rwm-tab';tab.dataset.rwmTab='health';tab.textContent='Health';root.querySelector('.rwm-tabs').appendChild(tab);var panel=document.createElement('section');panel.className='rwm-panel';panel.dataset.rwmPanel='health';panel.innerHTML=scene('Trail Mesh health','Live checks, errors and the next recommended action','🩺')+'<div class="rwm-card"><h3>What to do next</h3><div id="rwmNextStep" class="rwm-next"></div><div class="rwm-row" style="margin-top:10px"><button id="rwmHealthRefresh" class="rwm-btn">Run health check</button><button id="rwmCopyLog" class="rwm-btn secondary">Copy report</button><button id="rwmClearLog" class="rwm-btn secondary">Clear</button></div></div><div class="rwm-card"><h3>Permissions · requested only on use</h3><p class="rwm-note">These are the Android capabilities RoamWise can use. Every toggle starts off; the related feature asks at the moment you choose it. Normal network access, vibration and the system file picker do not need runtime consent.</p><div id="rwmPermissionCatalog"></div></div><div class="rwm-card"><h3>Process console</h3><p class="rwm-note">Stored only on this phone. It records Trail Mesh actions and errors, not message contents or selected files.</p><div id="rwmConsole" class="rwm-console"></div></div>';root.querySelector('.rwm-body').appendChild(panel);tab.onclick=function(){selectTab('health');renderConsole();};panel.querySelector('#rwmHealthRefresh').onclick=function(){act('Health check',runSelfTest);};panel.querySelector('#rwmCopyLog').onclick=copyHealthReport;panel.querySelector('#rwmClearLog').onclick=function(){state.logs=[];try{localStorage.removeItem('rw_mesh_health_log');}catch(_){}trace('info','Console','Log cleared');};}
    var art={chat:['Trail radio room','Text and voice notes across the group','💬'],team:['Keep the line together','Roll calls, regrouping and lost-trekker alerts','🧭'],sos:['Help travels outward','Local alarm and verified nearby SOS relay','🆘'],share:['Pass memories phone to phone','Photos, songs and short videos without data','📸'],guide:['Ready before the trail','Practice together while mobile service still works','🥾']};
    Object.keys(art).forEach(function(name){var panel=root.querySelector('[data-rwm-panel="'+name+'"]');if(panel&&!panel.querySelector('.rwm-scene'))panel.insertAdjacentHTML('afterbegin',scene(art[name][0],art[name][1],art[name][2]));});
    var connect=root.querySelector('[data-rwm-panel="connect"]');
    if(connect&&!connect.querySelector('#rwmRadarCard')){var radar=document.createElement('div');radar.className='rwm-card';radar.id='rwmRadarCard';radar.innerHTML='<h3>Nearby radar</h3><p class="rwm-note">The radar shows phones discovered by the local radio scan. A dot is not a verified connection until both people compare the pairing digits and accept.</p><div id="rwmRadar" class="rwm-radar" aria-label="Nearby device radar"></div><div id="rwmPairings" class="rwm-test"><div class="rwm-check wait">○ No pairing request waiting</div></div><div class="rwm-row"><input id="rwmPairCode" class="rwm-input" inputmode="numeric" maxlength="8" placeholder="Pairing digits to share"><button id="rwmSharePairing" class="rwm-btn secondary">Share digits manually</button></div><p class="rwm-note rwm-tip">Manual sharing sends the digits through your chosen system share sheet or clipboard. It does not bypass the in-person verification step.</p>';connect.insertBefore(radar,connect.lastElementChild);radar.querySelector('#rwmSharePairing').onclick=function(){sharePairing();};}
    var guide=root.querySelector('[data-rwm-panel="guide"]');
    if(guide&&!guide.querySelector('#rwmFeatureGuide'))guide.insertAdjacentHTML('beforeend','<div class="rwm-card" id="rwmFeatureGuide"><h3>Feature-by-feature field guide</h3><p class="rwm-note rwm-tip"><b>Connect:</b> Start on every phone before departure, compare verification digits face to face, then run the teammate test with airplane mode on and Bluetooth/Wi-Fi re-enabled.</p><p class="rwm-note rwm-tip"><b>Chat:</b> Use text for fast updates and short voice notes when gloves or darkness make typing difficult. Messages need at least one verified peer.</p><p class="rwm-note rwm-tip"><b>Team:</b> Set a checkpoint, run roll calls at junctions, and use Hold position before searching for a missing person.</p><p class="rwm-note rwm-tip"><b>SOS:</b> Describe injury, clothing and direction; tick Attach precise location only when you consciously want Android to request it. Sound the alarm to help nearby searchers, but call emergency services whenever possible.</p><p class="rwm-note rwm-tip"><b>Share:</b> Select a file up to 64 MB and keep both screens open until complete. Files above 8 MB show a confirmation warning; prefer compressed media to preserve battery and radio capacity.</p><p class="rwm-note rwm-tip"><b>Fun:</b> Start a tiny challenge for the group. Activities send only text; use Share separately for the winning photo or song.</p><p class="rwm-note rwm-tip"><b>Travel characters:</b> Choose a local character in Fun, ask a short question, and use Read last reply for offline voice playback. Treat replies as entertainment and planning prompts—not a substitute for a guide, map, weather report, or emergency service.</p><p class="rwm-note rwm-tip"><b>Battery:</b> Keep the two-hour guard on for casual use. Turn it off only for a planned long session, and stop Trail Mesh at camp or journey end.</p></div><div class="rwm-card" id="rwmMountainContext"><h3>Why this matters in the mountains</h3><p class="rwm-note">Mountain travel can move from connected to isolated within one bend. Deep valleys, forest, rock, snow, weather and crowds can weaken both mobile coverage and local radio range. Trail Mesh gives a prepared group a short-range coordination layer while their phones can still reach one another.</p><p class="rwm-note rwm-tip"><b>Uttarakhand:</b> On pilgrim routes, forest approaches and treks around places such as Kedarkantha, Valley of Flowers or the approaches to high-altitude camps, a group may stretch between switchbacks or separate at tea stops. Use named checkpoints, junction roll calls and Hold position before anyone turns back to search.</p><p class="rwm-note rwm-tip"><b>Himachal Pradesh:</b> On wooded trails, ridge crossings and busy routes around Manali, Parvati Valley, Dharamshala and Spiti approaches, use offline chat for pace changes, water breaks and vehicle rendezvous. Place willing relay phones between the leader and rear marker instead of clustering every phone together.</p><p class="rwm-note rwm-tip"><b>Everest region:</b> International roaming and lodge Wi-Fi may be intermittent, and terrain can block radio line-of-sight. Prepare names and test at the trailhead; use Trail Mesh only for companions within local phone-radio range. For high-altitude expeditions, carry appropriate satellite communication, trained guides and an established rescue plan.</p><p class="rwm-note rwm-tip"><b>Ladakh and other remote regions:</b> Long road gaps, sparse coverage and widely separated viewpoints make a pre-agreed regroup point valuable. Use concise text, avoid large media during an incident, preserve power, and keep a rear marker with the slower members.</p><p class="rwm-note"><b>A useful pattern:</b> leader at the front, a designated rear marker, relay volunteers spaced through the group, and a fixed checkpoint/time everyone understands before moving. A forwarded alert proves only that another phone relayed it—not that rescuers received it.</p></div><div class="rwm-card"><h3>A trailhead story</h3><p class="rwm-note">Imagine twelve trekkers leaving before sunrise. The leader reaches a fork while mist hides the rear group; two people stop to help with a loose boot, and mobile service disappears. Because the team paired Trail Mesh before departure, the rear marker sends “delayed 10 minutes,” the middle relay forwards it, and the leader replies “holding at the marked bridge.” Nobody guesses which path to take. That small moment—prepared names, verified phones and one clear checkpoint—is the job Trail Mesh is designed to support.</p></div>');
    renderPermissionCatalog();
  }

  function renderPermissionCatalog(){var box=document.getElementById('rwmPermissionCatalog');if(!box)return;var rows=[['Nearby radios','Bluetooth scan/connect/advertise + Nearby Wi‑Fi','Connect → Allow & start','Required only while Trail Mesh runs'],['Legacy location','Android 12 and older Nearby compatibility','Connect → Allow & start on legacy devices','Android 13+ does not request location for Nearby'],['Precise location','High-accuracy location-assisted SOS','SOS → tick Attach precise location','Requested only when the SOS flow uses the location'],['Microphone','Push-to-talk voice notes','Chat → Record radio note','Requested only when recording starts'],['Camera','Optional photo capture','Fun/Share → choose a camera action','Not requested by Trail Mesh; the system picker can be used'],['Notifications','Optional status/emergency notifications','Only when an opt-in notification feature is enabled','Off by default'],['Files and media','Selected file transfer','Share → Choose file','Uses the system picker; no broad storage permission'],['Network and vibration','Online fallback and local alarm','Feature-specific use','Normal capabilities; no runtime prompt']];box.innerHTML=rows.map(function(r){return '<div class="rwm-check wait"><input type="checkbox" disabled aria-label="'+esc(r[0])+' permission toggle"> <span><b>'+esc(r[0])+'</b><br>'+esc(r[1])+'<br><small>'+esc(r[2])+' · '+esc(r[3])+'</small></span></div>';}).join('');}
  function renderRadar(){var radar=document.getElementById('rwmRadar');if(!radar)return;var peers=Object.keys(state.peers);radar.innerHTML=peers.map(function(key,index){var angle=(index*137.5)%360, radius=22+(index%3)*17, x=50+Math.cos(angle*Math.PI/180)*radius, y=50+Math.sin(angle*Math.PI/180)*radius;return '<span class="rwm-dot" title="'+esc(state.peers[key].name||'Nearby trekker')+'" style="left:'+x+'%;top:'+y+'%"></span>';}).join('');}
  function renderPairings(){var box=document.getElementById('rwmPairings');if(!box)return;var keys=Object.keys(state.pendingPairings);if(!keys.length){box.innerHTML='<div class="rwm-check wait">○ No pairing request waiting</div>';return;}box.innerHTML=keys.map(function(key){var p=state.pendingPairings[key];return '<div class="rwm-card"><b>Pair with '+esc(p.name||'Nearby trekker')+'</b><p class="rwm-note">Compare these digits in person on both phones:</p><div style="font-size:28px;letter-spacing:.25em;color:var(--gold,#E8BA6C)">'+esc(p.code||'Unavailable')+'</div><div class="rwm-row"><button class="rwm-btn" data-rwm-accept="'+esc(key)+'">Accept matching digits</button><button class="rwm-btn secondary" data-rwm-reject="'+esc(key)+'">Reject</button></div></div>';}).join('');box.querySelectorAll('[data-rwm-accept]').forEach(function(b){b.onclick=function(){acceptPairing(b.dataset.rwmAccept);};});box.querySelectorAll('[data-rwm-reject]').forEach(function(b){b.onclick=function(){rejectPairing(b.dataset.rwmReject);};});}
  function renderTransfers(){var box=document.getElementById('rwmTransfers');if(!box)return;Object.keys(state.received).forEach(function(key){var f=state.received[key],item=document.getElementById('rwmTransfer-'+key);if(!item){item=document.createElement('div');item.id='rwmTransfer-'+key;item.className='rwm-card';box.prepend(item);}item.innerHTML='<div>Received '+esc(f.name)+' · '+formatBytes(f.size)+'</div><div class="rwm-progress"><i style="width:100%"></i></div><div class="rwm-row"><button class="rwm-btn" data-rwm-open="'+esc(key)+'">Open</button><button class="rwm-btn secondary" data-rwm-save="'+esc(key)+'">Save</button></div>';item.querySelector('[data-rwm-open]').onclick=function(){openBlob(f.url);};item.querySelector('[data-rwm-save]').onclick=function(){saveBlob(f.url,f.name);};});}
  function acceptPairing(endpointId){var p=state.pendingPairings[endpointId];if(!p)return;try{requirePlugin().acceptConnection({endpointId:endpointId}).then(function(){delete state.pendingPairings[endpointId];trace('ok','Pairing','Accepted '+(p.name||'nearby trekker'));render();}).catch(function(e){trace('error','Pairing',e.message||'Could not accept pairing');toast(e.message||'Could not accept pairing');});}catch(e){trace('error','Pairing',e.message||'Could not accept pairing');toast(e.message||'Could not accept pairing');}}
  function rejectPairing(endpointId){var p=state.pendingPairings[endpointId];delete state.pendingPairings[endpointId];renderPairings();if(plugin())plugin().rejectConnection({endpointId:endpointId}).catch(function(){});trace('info','Pairing','Rejected '+((p&&p.name)||'nearby trekker'));}
  function sharePairing(){var input=document.getElementById('rwmPairCode'),code=(input&&input.value||'').replace(/\D/g,'');if(!/^\d{4,8}$/.test(code)){toast('Enter the pairing digits shown on both phones');return;}var text='RoamWise Trail Mesh pairing digits: '+code+'\nCompare in person before accepting. These digits do not install the app or bypass verification.';if(navigator.share){navigator.share({title:'RoamWise pairing digits',text:text}).then(function(){trace('ok','Pairing','Digits shared manually');}).catch(function(){});}else if(navigator.clipboard){navigator.clipboard.writeText(text).then(function(){toast('Pairing digits copied');trace('ok','Pairing','Digits copied manually');}).catch(function(){toast(text);});}else toast(text);}
  function renderConsole(){var next=document.getElementById('rwmNextStep'),box=document.getElementById('rwmConsole');if(next)next.textContent=nextStep();if(box)box.innerHTML=state.logs.slice().reverse().map(function(x){return '<div class="rwm-log '+esc(x.level)+'"><b>'+esc(x.at)+' · '+esc(x.step)+'</b><br>'+esc(x.message)+'</div>';}).join('')||'<div class="rwm-log">No events yet. Run the health check.</div>';renderPermissionCatalog();}
  function copyHealthReport(){var report='RoamWise Trail Mesh health\nMode: '+(state.demo?'DEMO':state.running?'RUNNING':'STOPPED')+'\nNext: '+nextStep()+'\n'+state.logs.map(function(x){return x.at+' ['+x.level+'] '+x.step+': '+x.message;}).join('\n');if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(report).then(function(){toast('Health report copied');}).catch(function(){toast('Could not copy report');});else toast('Clipboard unavailable');}

  function open(tab) {
    styles(); var overlay = document.getElementById('rwMeshOverlay');
    if (!overlay) { overlay = document.createElement('div'); overlay.id = 'rwMeshOverlay'; overlay.innerHTML = template(); document.body.appendChild(overlay); decoratePanels(overlay); installDiagnosticCard(overlay); bindUI(overlay); }
    overlay.style.display = 'block'; var fab=document.getElementById('rwMeshFab');if(fab)fab.style.display='none';document.body.style.overflow = 'hidden'; selectTab(tab || 'connect'); render();
  }
  function close() { var o = document.getElementById('rwMeshOverlay'); if (o) o.style.display = 'none'; var fab=document.getElementById('rwMeshFab');if(fab)fab.style.display='';document.body.style.overflow = ''; stopAlarm(); }
  function selectTab(name) { document.querySelectorAll('[data-rwm-tab]').forEach(function (x) { x.classList.toggle('active', x.dataset.rwmTab === name); }); document.querySelectorAll('[data-rwm-panel]').forEach(function (x) { x.classList.toggle('active', x.dataset.rwmPanel === name); }); }
  function render() {
    var status = document.getElementById('rwmStatus'); if (status) { status.textContent = state.demo ? 'DEMO · simulated' : state.running ? 'Running · ' + peerCount() + ' connected' : 'Stopped'; status.className = 'rwm-badge ' + (state.running ? 'rwm-good' : ''); }
    var pc = document.getElementById('rwmPeerCount'); if (pc) pc.textContent = String(peerCount());
    var peers = document.getElementById('rwmPeers'); if (peers) { var list = Object.keys(state.peers).map(function (key) { var p = state.peers[key]; return '<div class="rwm-msg"><b>'+esc(p.name || 'Nearby trekker')+'</b><div class="rwm-meta">'+esc(p.connected ? 'Connected and verified' : p.found ? 'Discovered' : 'Disconnected')+'</div></div>'; }); peers.innerHTML = list.join('') || 'No connected trekkers yet.'; }
    var messages = document.getElementById('rwmMessages'); if (messages) { messages.innerHTML = state.messages.slice(-100).map(function (m) { return '<div class="rwm-msg '+(m.mine?'mine':'')+'"><b>'+esc(m.from)+'</b> '+esc(m.text)+'<div class="rwm-meta">'+esc(m.time)+'</div></div>'; }).join('') || '<p class="rwm-note">No offline messages yet.</p>'; messages.scrollTop = messages.scrollHeight; }
    var funFeed=document.getElementById('rwmFunFeed');if(funFeed)funFeed.innerHTML=state.funEvents.slice(-8).reverse().map(function(e){return '<div class="rwm-check '+(e.ok?'pass':'fail')+'">'+(e.ok?'✓ ':'✕ ')+esc(e.text)+' <span class="rwm-meta">'+esc(e.time)+'</span></div>';}).join('')||'<div class="rwm-check wait">○ Choose a challenge to begin</div>';
    var aiFeed=document.getElementById('rwmAiMessages');if(aiFeed)aiFeed.innerHTML=state.aiMessages.slice(-12).map(function(m){return '<div class="rwm-msg '+(m.mine?'mine':'')+'"><b>'+esc(m.from)+'</b> '+esc(m.text)+'<div class="rwm-meta">'+esc(m.time)+'</div></div>';}).join('')||'<div class="rwm-check wait">○ Choose a character and say hello</div>';
    renderRadar();
    renderPairings();
    renderTransfers();
    var portrait=document.getElementById('rwmCharacterPortrait'),character=document.getElementById('rwmCharacter');if(portrait&&character){var icons={nanda:'🏔️',tenzing:'🗻',himachali:'🌲',ladakhi:'🏜️'};portrait.textContent=icons[character.value]||'🧭';}
    renderDiagnostic();
    renderConsole();
  }

  function installDiagnosticCard(root) {
    if (root.querySelector('#rwmSelfTest')) return;
    var panel=root.querySelector('[data-rwm-panel="connect"]'), card=document.createElement('div');
    card.className='rwm-card';
    card.innerHTML='<h3>Offline readiness test</h3><p class="rwm-note">Switch off mobile data and internet first. The one-phone check proves permissions and the local Nearby engine. The teammate test proves a real device-to-device message and reply.</p><div class="rwm-row"><button id="rwmSelfTest" class="rwm-btn">Run offline check</button><button id="rwmPeerTest" class="rwm-btn secondary">Test with teammate</button><button id="rwmDemo" class="rwm-btn secondary">Try with demo trekker</button></div><p class="rwm-note rwm-tip">Demo mode checks the interface and feature flows on one phone. It is clearly simulated and never counts as proof that Nearby radio works.</p><div id="rwmTestResults" class="rwm-test"><div class="rwm-check wait">○ No test run yet</div></div>';
    panel.insertBefore(card,panel.lastElementChild);
    card.querySelector('#rwmSelfTest').onclick=runSelfTest;
    card.querySelector('#rwmPeerTest').onclick=runPeerTest;
    card.querySelector('#rwmDemo').onclick=startDemo;
  }
  function renderDiagnostic() {
    var el=document.getElementById('rwmTestResults'); if(!el)return;
    var d=state.diagnostic, rows=[];
    if(d){rows.push([d.native,'Native Trail Mesh bridge loaded']);rows.push([d.granted,'Required runtime permissions granted']);if(d.legacyLocationNeeded)rows.push([d.legacyLocationGranted,'Legacy Android location permission available for Nearby']);if(d.accessWifiState!==undefined)rows.push([d.accessWifiState,'ACCESS_WIFI_STATE available to Google Nearby']);if(d.changeWifiState!==undefined)rows.push([d.changeWifiState,'CHANGE_WIFI_STATE available to Google Nearby']);rows.push([d.running,'Discovery and advertising running']);rows.push([d.offline,'Internet appears off (expected for blackout test)']);rows.push([d.topology,'P2P cluster radio topology ready']);}
    if(state.peerTest)rows.push([state.peerTest.pass,state.peerTest.text]);
    if(!rows.length)return;
    el.innerHTML=rows.map(function(r){var cls=r[0]===true?'pass':r[0]===false?'fail':'wait';return '<div class="rwm-check '+cls+'">'+(r[0]===true?'✓':r[0]===false?'✕':'…')+' '+esc(r[1])+'</div>';}).join('');
  }
  async function runSelfTest() {
    var d={native:Boolean(plugin()),granted:false,running:false,offline:navigator.onLine===false,topology:false};
    try{var s=await requirePlugin().getStatus();d.granted=Boolean(s.granted);d.legacyLocationNeeded=Number(s.sdkInt||99)<=31;d.legacyLocationGranted=Number(s.sdkInt||99)<=28?Boolean(s.coarseLocationGranted):Boolean(s.fineLocationGranted);d.accessWifiState=Boolean(s.accessWifiStateDeclared);d.changeWifiState=Boolean(s.changeWifiStateDeclared);d.running=Boolean(s.running)&&!state.demo;d.topology=s.topology==='P2P_CLUSTER';}catch(e){d.error=e.message;trace('error','Health check',d.error);}
    state.diagnostic=d;renderDiagnostic();
    if(d.native&&d.granted&&d.running&&d.topology)toast(d.offline?'Offline readiness passed — now test with a teammate':'Radio engine ready. Switch off internet and rerun for blackout proof.');else toast('Offline readiness needs attention — review the failed checks.');
  }
  async function runPeerTest() {
    if(state.demo){state.peerTest={pass:true,text:'Demo round trip passed — simulation only; this does not prove nearby radios'};renderDiagnostic();cue('success');return;}
    if(!state.running){state.peerTest={pass:false,text:'Start Trail Mesh before teammate test'};renderDiagnostic();return;}
    if(!peerCount()){state.peerTest={pass:false,text:'No verified teammate connected — start Trail Mesh on a second phone and match the verification digits'};renderDiagnostic();return;}
    var testId=id();state.transfers['ping:'+testId]=Date.now();state.peerTest={id:testId,pass:null,text:'Waiting up to 12 seconds for an offline reply…'};renderDiagnostic();
    try{await sendPacket('ping',{testId:testId,from:safeName()});}catch(e){state.peerTest={pass:false,text:'Could not send test: '+e.message};renderDiagnostic();return;}
    setTimeout(function(){if(state.peerTest&&state.peerTest.id===testId&&state.peerTest.pass===null){state.peerTest={pass:false,text:'No reply received — keep both apps open, nearby, verified, with Bluetooth and Wi-Fi enabled'};renderDiagnostic();}},12000);
  }

  function showStartError(message) { state.startError=message||'';var el=document.getElementById('rwmStartError');if(!el)return;el.classList.toggle('show',Boolean(message));el.innerHTML=message?'<b>Trail Mesh could not start</b><p>'+esc(message)+'</p><button id="rwmSettings" class="rwm-btn secondary">Open Android app settings</button><p class="rwm-note rwm-tip">Keep Bluetooth and Wi-Fi switched on, allow Nearby devices, then return and tap Allow & start again. This is local Android setup—not Firestore.</p>':'';var b=document.getElementById('rwmSettings');if(b)b.onclick=function(){requirePlugin().openAppSettings();}; }
  async function start() { trace('info','Start','Checking Android permissions and radios');try{stopDemo(false);showStartError('');var button=document.getElementById('rwmStart');button.disabled=true;button.textContent='Starting radios…';var name=document.getElementById('rwmName').value.trim()||safeName();localStorage.setItem('rw_mesh_name',name);await requirePlugin().requestMeshPermissions();trace('ok','Permissions','Required grants are available');await requirePlugin().start({displayName:name});state.running=true;if(state.ecoTimer)clearTimeout(state.ecoTimer);if(document.getElementById('rwmEco').checked)state.ecoTimer=setTimeout(function(){stop();toast('Trail Mesh stopped by the 2-hour battery guard');},7200000);trace('ok','Start','Advertising and discovery started');render();cue('success');toast('Trail Mesh is running nearby');}catch(e){var raw=e.message||'Could not start Trail Mesh',msg=raw;if(/8034|MISSING_PERMISSION_ACCESS_COARSE_LOCATION/i.test(raw))msg='Google Nearby rejected the legacy location check. On Android 12 or older, allow the requested location permission; on Android 13+, install the latest build so only Nearby/Bluetooth/Wi‑Fi are required.';else if(/8032|MISSING_PERMISSION_ACCESS_WIFI_STATE/i.test(raw))msg='This build is missing Android’s normal ACCESS_WIFI_STATE capability required by Google Nearby. Install the latest build; no extra permission prompt is needed.';state.startError=raw;trace('error','Start',raw);showStartError(msg);cue('alert');}finally{var b=document.getElementById('rwmStart');if(b){b.disabled=false;b.textContent='Allow & start';}renderConsole();} }
  function startDemo(){state.demo=true;state.running=true;state.peers={'demo-nanda':{name:'Nanda · Demo trekker',found:true,connected:true}};state.messages.push({mine:false,from:'Trail Mesh',text:'Demo trekker joined. Try Chat, Team, Fun and SOS. Nothing leaves this phone.',time:now()});state.peerTest=null;showStartError('');render();selectTab('chat');cue('success');toast('Simulation started — no radio connection is claimed');}
  function stopDemo(show){if(!state.demo)return;state.demo=false;state.running=false;delete state.peers['demo-nanda'];state.peerTest=null;render();if(show!==false)toast('Demo trekker removed');}
  async function stop() { try { if(state.demo){stopDemo(true);trace('ok','Stop','Demo stopped');return;}await requirePlugin().stop();if(state.ecoTimer)clearTimeout(state.ecoTimer);state.ecoTimer=null;state.running=false;state.peers={};render();trace('ok','Stop','Nearby radios stopped');toast('Trail Mesh stopped'); } catch (e) { trace('error','Stop',e.message||'Could not stop');toast(e.message || 'Could not stop Trail Mesh'); } }
  async function sendChat(text, source) { text = String(text || '').trim(); if (!text) throw new Error('Type a message first'); await sendPacket('chat', { text: text, source: source || 'mesh', from: safeName() }); state.messages.push({ mine: true, from: 'You', text: text, time: now() }); render(); }
  function mirrorToTripChat(message) { var box = document.querySelector('#groupChatMessages,.group-chat-messages,#tripChatMessages'); if (!box) return; var row = document.createElement('div'); row.className = 'chat-message mesh-message'; row.innerHTML = '<b>📡 '+esc(message.from || 'Nearby trekker')+'</b><div>'+esc(message.text)+'</div><small>Offline Trail Mesh · '+esc(now())+'</small>'; box.appendChild(row); }

  async function networkTest() { return runPeerTest(); }
  async function radioCheck() { await sendPacket('team',{action:'radio-check',text:'Radio check — reply SAFE with your name and position',from:safeName()}); state.messages.push({mine:true,from:'Radio room',text:'Radio check sent',time:now()}); render(); }
  async function fun(kind) { var prompts={photo:'Photo challenge: capture the best trail view in 10 minutes 📷',story:'Campfire round: share a two-minute travel story 🔥',quiz:'Trail quiz: leader, send the next nature or navigation question 🧭',cheer:'Team cheer from '+safeName()+' 🙌',scavenger:'Scavenger hunt: find a heart-shaped stone, three leaf colours, or an animal track 🍃',summit:'Summit countdown: share your ETA and one word for the final push 🏁'};try{await sendPacket('fun',{kind:kind,text:prompts[kind],from:safeName()});state.messages.push({mine:true,from:'Trail fun',text:prompts[kind],time:now()});state.funEvents.push({ok:true,text:prompts[kind]+(state.demo?' · simulated':' · sent nearby'),time:now()});trace('ok','Fun',kind+' challenge sent');render();cue('success');}catch(e){state.funEvents.push({ok:false,text:(e&&e.message)||'Start Trail Mesh or demo first',time:now()});trace('error','Fun',(e&&e.message)||'Challenge failed');render();throw e;} }
  function characterReply(character,question){var q=String(question||'').toLowerCase();if(/sos|emergency|injur|lost|rescue|danger/.test(q))return 'I am a story companion, not emergency support. Use the SOS tab, contact local services, and follow your trek leader’s plan.';var replies={nanda:'Namaste! I’m Nanda from the Uttarakhand trails. Keep one warm layer and water handy; on a misty switchback, agree on a named checkpoint before moving.',tenzing:'Welcome to the high passes. In the Everest region, move slowly, protect batteries from cold, and confirm your guide’s weather and acclimatisation plan before a big day.',himachali:'Jai pahad! I’m Maya, your Himachal trail ranger. Tell the group your turnaround time, watch changing cloud over ridges, and leave no food waste near camp.',ladakhi:'Julley! I’m Tashi from Ladakh. Dry air and altitude can fool you—sip water, pace steadily, and keep a rear marker on long road or valley sections.'};if(/food|eat|cook/.test(q))return replies[character]+' For food, choose a simple high-energy snack the whole group can share.';if(/pack|bag|gear|carry/.test(q))return replies[character]+' Pack light: layers, headlamp, first-aid basics, power bank, water and a paper backup of key contacts.';if(/story|tell|fun|joke/.test(q))return replies[character]+' Here is a camp prompt: each trekker shares one surprising sound they heard today.';return replies[character]+' Ask me about pacing, packing, camp etiquette, a story prompt or a route-planning checklist.';}
  async function talkToCharacter(){var select=document.getElementById('rwmCharacter'),input=document.getElementById('rwmAiInput');var character=select&&select.value||'nanda',question=input&&input.value.trim();if(!question)throw new Error('Ask your trail character a question first');var names={nanda:'Nanda · Uttarakhand guide',tenzing:'Tenzing · Everest storyteller',himachali:'Maya · Himachal ranger',ladakhi:'Tashi · Ladakh navigator'};state.aiMessages.push({mine:true,from:'You',text:question,time:now()});if(input)input.value='';render();trace('info','Trail character','Question answered locally; no permission or internet needed');await new Promise(function(resolve){setTimeout(resolve,260);});state.aiMessages.push({mine:false,from:names[character],text:characterReply(character,question),time:now()});render();cue('success');}
  function speakLastCharacter(){var reply=state.aiMessages.slice().reverse().find(function(m){return !m.mine;});if(!reply)throw new Error('Ask your trail character a question first');if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window))throw new Error('Voice playback is not available on this Android device');window.speechSynthesis.cancel();var utterance=new SpeechSynthesisUtterance(reply.text);utterance.rate=.94;utterance.pitch=1.03;window.speechSynthesis.speak(utterance);trace('ok','Trail character','Voice playback started');}
  async function team(kind) { var cp = (document.getElementById('rwmCheckpoint').value || '').trim(); var labels = { rollcall: 'Roll call: reply that you are safe', regroup: 'Regroup' + (cp ? ' at '+cp : ' at the agreed checkpoint'), hold: 'Hold position and wait for the leader' }; await sendPacket('team', { action: kind, text: labels[kind], from: safeName() }); state.messages.push({ mine: true, from: 'Team command', text: labels[kind], time: now() }); render(); toast('Team command broadcast nearby'); }
  async function lost() { var name = document.getElementById('rwmLostName').value.trim(); if (!name) throw new Error('Add the lost trekker’s name or description'); if (!confirm('Broadcast this lost-trekker alert to all connected nearby devices?')) { trace('info','Lost trekker','Cancelled by user'); return; } await sendPacket('lost', { person: name, from: safeName() }); toast('Lost-trekker alert broadcast nearby'); }
  async function getLocation() { try { var pos = await new Promise(function (resolve, reject) { navigator.geolocation.getCurrentPosition(resolve, reject, { enableHighAccuracy: true, timeout: 10000 }); }); return { lat: +pos.coords.latitude.toFixed(6), lng: +pos.coords.longitude.toFixed(6), accuracy: Math.round(pos.coords.accuracy) }; } catch (_) { return null; } }
  async function sos() { var type = document.getElementById('rwmSosType').value, details = document.getElementById('rwmSosDetails').value.trim(), includeLocation=Boolean(document.getElementById('rwmSosLocation')&&document.getElementById('rwmSosLocation').checked); if (!confirm(state.demo?'Run a simulated SOS? Nothing will leave this phone.':'Broadcast a nearby SOS? Delivery is not guaranteed. Contact emergency services when possible.')) return; var location=null;if(includeLocation&&!state.demo){if(!confirm('RoamWise will request precise location for this SOS only. Include it?'))return;location=await getLocation();}await sendPacket('sos',{emergency:type,details:details,location:location,from:safeName()});if(!state.demo)startAlarm();toast(state.demo?'Simulated SOS completed — no real alert sent':'SOS broadcast to connected nearby devices'); }
  var alarmCtx;
  function startAlarm() { stopAlarm(); var b = document.getElementById('rwmAlarm'); if (b) { b.classList.add('rwm-alarm'); b.textContent = 'Stop alarm'; } try { alarmCtx = new (window.AudioContext || window.webkitAudioContext)(); var o = alarmCtx.createOscillator(), g = alarmCtx.createGain(); o.frequency.value = 880; g.gain.value = .2; o.connect(g); g.connect(alarmCtx.destination); o.start(); alarmCtx.oscillator = o; } catch (_) {} if (navigator.vibrate) navigator.vibrate([500,250,500,250,1000]); }
  function stopAlarm() { if (alarmCtx) { try { alarmCtx.close(); } catch (_) {} alarmCtx = null; } if (navigator.vibrate) navigator.vibrate(0); var b = document.getElementById('rwmAlarm'); if (b) { b.classList.remove('rwm-alarm'); b.textContent = 'Sound local alarm'; } }

  function bytesToBase64(bytes) { var out = ''; for (var i=0;i<bytes.length;i++) out += String.fromCharCode(bytes[i]); return btoa(out); }
  function base64ToBytes(value) { var raw = atob(value), out = new Uint8Array(raw.length); for (var i=0;i<raw.length;i++) out[i] = raw.charCodeAt(i); return out; }
  async function shareFile(file) {
    if (!file) throw new Error('Choose a file first');
    if (file.size > MAX_BRIDGE_FILE_BYTES) throw new Error('This mobile bridge safely supports files up to 64 MB. For 2–10 GB, compress or split the file until native streaming is available.');
    if (file.size > MAX_FILE_BYTES && !confirm('This file is larger than 8 MB ('+formatBytes(file.size)+'). It may take a long time and use substantial battery and radio time. Send it anyway?')) {
      trace('info','File share','Large-file transfer cancelled');
      return;
    }
    if (!state.running || !peerCount()) throw new Error('Start Trail Mesh and connect a verified device first');
    var transferId=id(), total=Math.ceil(file.size/CHUNK_BYTES);
    updateTransfer(transferId,'Preparing '+file.name+' · '+formatBytes(file.size),0);
    if (state.demo) {
      await new Promise(function(resolve){setTimeout(resolve,550);});
      updateTransfer(transferId,'Simulated '+file.name+' · no file transmitted',1);
      trace('ok','File share','Simulation completed; no file transmitted');
      toast('Simulated share — no file left this phone');
      return;
    }
    await sendPacket('file-start',{transferId:transferId,name:file.name,mime:file.type||'application/octet-stream',size:file.size,total:total});
    for (var i=0;i<total;i++) {
      var bytes=new Uint8Array(await file.slice(i*CHUNK_BYTES,(i+1)*CHUNK_BYTES).arrayBuffer());
      await sendPacket('file-chunk',{transferId:transferId,index:i,value:bytesToBase64(bytes)});
      if (i===0||i===total-1||i%Math.max(1,Math.floor(total/20))===0) updateTransfer(transferId,'Sending '+file.name+' · '+formatBytes(file.size),(i+1)/total);
    }
    await sendPacket('file-end',{transferId:transferId});
    updateTransfer(transferId,'Shared '+file.name+' · '+formatBytes(file.size),1);
    toast('Shared '+file.name+' nearby');
  }
  function updateTransfer(key,label,ratio,link) { var el=document.getElementById('rwmTransfers');if(!el)return;var item=document.getElementById('rwmTransfer-'+key);if(!item){item=document.createElement('div');item.id='rwmTransfer-'+key;item.className='rwm-card';el.prepend(item);}item.innerHTML='<div>'+esc(label)+'</div><div class="rwm-progress"><i style="width:'+Math.round(ratio*100)+'%"></i></div>'+(link||''); }
  function saveBlob(url,name){var a=document.createElement('a');a.href=url;a.download=name||'roamwise-transfer';a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();setTimeout(function(){a.remove();},1000);}
  function openBlob(url){var w=window.open(url,'_blank');if(!w)window.location.href=url;}
  function receiveFile(p) {
    var d=p.data||{}, transferId=String(d.transferId||''), t=state.transfers[transferId];
    if (!transferId) { trace('error','File receive','Ignored a transfer without an id'); return; }
    if (p.type==='file-start') {
      var size=Number(d.size), total=Number(d.total);
      if (!Number.isFinite(size)||size<1||size>MAX_BRIDGE_FILE_BYTES||!Number.isInteger(total)||total<1||total>Math.ceil(MAX_BRIDGE_FILE_BYTES/CHUNK_BYTES)) {
        trace('error','File receive','Rejected an invalid or oversized transfer');
        toast('Incoming file is too large for this mobile bridge');
        return;
      }
      state.transfers[transferId]={name:String(d.name||'received-file'),mime:String(d.mime||'application/octet-stream'),size:size,total:total,chunks:[]};
      updateTransfer(transferId,'Receiving '+String(d.name||'received-file')+' · '+formatBytes(size),0);
    } else if (p.type==='file-chunk'&&t) {
      var index=Number(d.index);
      if (!Number.isInteger(index)||index<0||index>=t.total||typeof d.value!=='string') { trace('error','File receive','Ignored an invalid file chunk'); return; }
      try { t.chunks[index]=base64ToBytes(d.value); } catch (_) { trace('error','File receive','Ignored an unreadable file chunk'); return; }
      var received=t.chunks.filter(Boolean).length;
      if (received===1||received===t.total||received%Math.max(1,Math.floor(t.total/20))===0) updateTransfer(transferId,'Receiving '+t.name+' · '+formatBytes(t.size),received/t.total);
    } else if (p.type==='file-end'&&t&&t.chunks.filter(Boolean).length===t.total) {
      var url=URL.createObjectURL(new Blob(t.chunks,{type:t.mime}));
      state.received[transferId]={name:t.name,mime:t.mime,size:t.size,url:url,at:Date.now()};
      Object.keys(state.received).sort(function(a,b){return (state.received[a].at||0)-(state.received[b].at||0);}).slice(0,-12).forEach(function(key){try{URL.revokeObjectURL(state.received[key].url);}catch(_){}delete state.received[key];});
      delete state.transfers[transferId];
      renderTransfers();
      trace('ok','File receive','Received '+t.name+'; Open and Save actions are ready');
      toast('Received '+t.name+' — choose Open or Save');
    }
  }
  async function toggleVoice() {
    if (state.recorder && state.recorder.state === 'recording') { state.recorder.stop(); return; }
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) throw new Error('Voice notes need the RoamWise Android app with microphone access enabled');
    if (!window.MediaRecorder) throw new Error('Voice recording is not available on this Android device');
    if (localStorage.getItem('rw_mesh_mic_disclosure') !== '1') {
      if (!confirm('Trail Mesh will use the microphone only while you record a push-to-talk radio note. The recording is shared only after you stop. Continue?')) throw new Error('Microphone request cancelled');
      localStorage.setItem('rw_mesh_mic_disclosure','1');
    }
    try {
      var stream = await navigator.mediaDevices.getUserMedia({ audio: true }), chunks = [];
      state.recorder = new MediaRecorder(stream);
      state.recorder.ondataavailable = function (e) { if (e.data.size) chunks.push(e.data); };
      state.recorder.onstop = function () {
        stream.getTracks().forEach(function (x) { x.stop(); });
        var blob = new Blob(chunks, { type: state.recorder.mimeType || 'audio/webm' });
        shareFile(new File([blob], 'trail-voice-'+Date.now()+'.webm', { type: blob.type })).catch(function(e){trace('error','Voice note',e.message||'Could not share recording');toast(e.message||'Could not share recording');});
        state.recorder = null;
        var b=document.getElementById('rwmVoice'); if(b)b.textContent='🎙 Record radio note';
      };
      state.recorder.start();
      var btn=document.getElementById('rwmVoice'); if(btn)btn.textContent='⏹ Send voice note';
      trace('info','Voice note','Recording started; release to send');
      setTimeout(function(){ if(state.recorder && state.recorder.state==='recording')state.recorder.stop(); },60000);
    } catch (e) {
      throw new Error(e && e.name==='NotAllowedError' ? 'Microphone access was declined. Allow it only while recording a radio note.' : 'Could not start the microphone for a voice note');
    }
  }

  function onPacket(event) { var p; try { p = JSON.parse(event.message); } catch (_) { p = { type:'chat', data:{ text:event.message, from:event.displayName } }; } if (!p || p.rw !== 1 && p.type !== 'chat') return; if(p.id&&state.seen[p.id])return; if(p.id){state.seen[p.id]=Date.now();Object.keys(state.seen).forEach(function(key){if(Date.now()-state.seen[key]>600000)delete state.seen[key];});} var d=p.data||{}; if (p.type==='chat') { var m={ mine:false, from:d.from||event.displayName||'Nearby trekker', text:d.text||'', time:now() }; state.messages.push(m); mirrorToTripChat(m); toast('Offline message from '+m.from); render(); } else if (p.type==='ping') { sendPacket('pong',{testId:d.testId,from:safeName()},event.endpointId); } else if (p.type==='pong') { var sent=state.transfers['ping:'+d.testId]; if(sent){ var latency=Date.now()-sent; state.peerTest={id:d.testId,pass:true,text:'Offline teammate reply received in '+latency+' ms — device-to-device messaging works'}; toast('Offline teammate test passed in '+latency+' ms'); delete state.transfers['ping:'+d.testId]; renderDiagnostic(); } } else if (p.type.indexOf('file-')===0) receiveFile(p); else if (p.type==='sos') { startAlarm(); open('sos'); toast('Nearby SOS from '+(d.from||'a trekker')+': '+(d.emergency||'Help needed')); } else if (p.type==='lost') { open('team'); toast('Lost-trekker alert: '+(d.person||'unknown person')); } else if (p.type==='team'||p.type==='fun') { state.messages.push({mine:false,from:(p.type==='fun'?'Trail fun':'Team')+' · '+(d.from||'Leader'),text:d.text,time:now()}); render(); toast(d.text||'New group message'); } relayPacket(p,event.endpointId); }
  async function listeners() {
    if (state.listeners || !plugin()) return;
    state.listeners=true;
    var p=plugin();
    await p.addListener('meshState',function(e){state.running=Boolean(e.running);render();});
    await p.addListener('peerFound',function(e){state.peers[e.endpointId]={name:e.displayName||'Nearby trekker',found:true,connected:false};trace('info','Radar','Nearby phone discovered: '+(e.displayName||'Nearby trekker'));render();});
    await p.addListener('peerLost',function(e){delete state.peers[e.endpointId];delete state.pendingPairings[e.endpointId];render();});
    await p.addListener('connectionChanged',function(e){state.peers[e.endpointId]=state.peers[e.endpointId]||{name:'Verified trekker'};state.peers[e.endpointId].connected=Boolean(e.connected);if(e.connected)delete state.pendingPairings[e.endpointId];if(!e.connected)state.peerTest=null;render();});
    await p.addListener('verificationRequired',function(e){
      state.pendingPairings[e.endpointId]={name:e.displayName||'Nearby trekker',code:e.verificationCode||'Unavailable'};
      trace('info','Pairing','Verification digits available for '+(e.displayName||'Nearby trekker')+'; compare them in person');
      open('connect');
      var pairingInput=document.getElementById('rwmPairCode');if(pairingInput&&e.verificationCode)pairingInput.value=String(e.verificationCode).replace(/\D/g,'').slice(0,8);
      toast('Pairing request ready in Nearby radar — compare the digits before accepting');
    });
    await p.addListener('messageReceived',onPacket);
    await p.addListener('meshError',function(e){var message=e.message||e.type||'Trail Mesh error';trace('error','Nearby',message);toast(message);});
  }

  function act(label,work){if(typeof label==='function'){work=label;label='Action';}trace('info',label,'Started');return Promise.resolve().then(work).then(function(value){trace('ok',label,'Completed');return value;}).catch(function(e){var message=(e&&e.message)||'Start Trail Mesh or try the demo trekker first';trace('error',label,message);toast(message);cue('alert');});}
  function bindUI(root) {
    root.querySelector('[data-rwm-close]').onclick=close;
    root.querySelectorAll('[data-rwm-tab]').forEach(function(x){x.onclick=function(){selectTab(x.dataset.rwmTab);};});
    root.querySelector('#rwmName').value=safeName();
    root.querySelector('#rwmStart').onclick=start;
    root.querySelector('#rwmStop').onclick=stop;
    root.querySelector('#rwmPing').onclick=networkTest;
    root.querySelector('#rwmRelay').checked=localStorage.getItem('rw_mesh_relay')==='1';
    state.relay=root.querySelector('#rwmRelay').checked;
    root.querySelector('#rwmRelay').onchange=function(e){state.relay=e.target.checked;localStorage.setItem('rw_mesh_relay',state.relay?'1':'0');trace('ok','Relay',state.relay?'Enabled':'Disabled');toast(state.relay?'Three-hop lightweight relay enabled':'Relay disabled');};
    root.querySelector('#rwmSend').onclick=function(){var x=root.querySelector('#rwmChatInput');act('Chat',function(){return sendChat(x.value).then(function(){x.value='';});});};
    root.querySelector('#rwmVoice').onclick=function(){act('Voice note',toggleVoice);};
    root.querySelector('#rwmRadioCheck').onclick=function(){act('Radio check',radioCheck);};
    root.querySelector('#rwmClearChat').onclick=function(){if(!state.messages.length){toast('Chat is already empty');return;}if(!confirm('Clear this phone’s Trail Mesh chat history?'))return;state.messages=[];trace('info','Chat','Local Trail Mesh history cleared');render();toast('Old chat cleared on this phone');};
    root.querySelectorAll('[data-rwm-team]').forEach(function(x){x.onclick=function(){act('Team '+x.dataset.rwmTeam,function(){return team(x.dataset.rwmTeam);});};});
    root.querySelectorAll('[data-rwm-fun]').forEach(function(x){x.onclick=function(){act('Fun '+x.dataset.rwmFun,function(){return fun(x.dataset.rwmFun);});};});
    root.querySelector('#rwmAiSend').onclick=function(){act('Trail character',talkToCharacter);};
    root.querySelector('#rwmAiSpeak').onclick=function(){act('Trail character voice',speakLastCharacter);};
    root.querySelector('#rwmCharacter').onchange=function(){render();};
    root.querySelector('#rwmAiClear').onclick=function(){state.aiMessages=[];if('speechSynthesis' in window)window.speechSynthesis.cancel();trace('info','Trail character','Conversation cleared');render();};
    root.querySelector('#rwmLost').onclick=function(){act('Lost trekker',lost);};
    root.querySelector('#rwmSOS').onclick=function(){act('SOS',sos);};
    root.querySelector('#rwmAlarm').onclick=function(){alarmCtx?stopAlarm():startAlarm();trace('ok','Alarm',alarmCtx?'Started':'Stopped');};
    root.querySelector('#rwmOfficialSOS').onclick=function(){close();if(typeof window.openSOS==='function'){trace('info','SOS','Opening official RoamWise SOS');window.openSOS();}else{trace('error','SOS','Official SOS screen is unavailable in this build');toast('Official RoamWise SOS is unavailable in this build');}};
    root.querySelector('#rwmShare').onclick=function(){act('File share',function(){return shareFile(root.querySelector('#rwmFile').files[0]);});};
  }

  function installEntryPoints() {
    if (!plugin()) return; styles(); listeners();
    if (!document.getElementById('rwMeshFab')) { var f=document.createElement('button');f.id='rwMeshFab';f.textContent='📡';f.title='Open Trail Mesh';f.setAttribute('aria-label','Open Trail Mesh');f.onclick=function(){open();};document.body.appendChild(f); }
    var groupItem=Array.from(document.querySelectorAll('button,a,.drawer-item,.menu-item')).find(function(x){return /group chat/i.test(x.textContent||'');}); if(groupItem && !document.getElementById('rwMeshMenu')){var item=groupItem.cloneNode(true);item.id='rwMeshMenu';item.removeAttribute('onclick');item.innerHTML='📡 Trail Mesh <span class="rwm-badge">OFFLINE</span>';item.onclick=function(e){e.preventDefault();open();};groupItem.parentNode.insertBefore(item,groupItem.nextSibling);}
    var chat=document.querySelector('#groupChatOverlay,.group-chat-overlay,#tripChatOverlay'); if(chat && !chat.querySelector('.rwm-chat-launch')){var b=document.createElement('button');b.className='rwm-btn rwm-chat-launch';b.textContent='📡 Mesh';b.onclick=function(){open('chat');};chat.insertBefore(b,chat.firstChild);}
  }
  function installBridges() {
    var originalTrip=window.tripChatSend; if(typeof originalTrip==='function'&&!originalTrip.__rwm){var wrapped=function(){var input=document.getElementById('tripChatInput');var value=input&&input.value;var result=originalTrip.apply(this,arguments);if(state.running&&value)sendChat(value,'trip-chat').catch(function(e){trace('error','Trip Chat bridge',e.message||'Could not send over mesh');});return result;};wrapped.__rwm=true;window.tripChatSend=wrapped;}
    var originalTusk=window.copilotSend; if(typeof originalTusk==='function'&&!originalTusk.__rwm){var tusk=function(){var input=document.getElementById('cpInput')||document.getElementById('heroInput');var q=(input&&input.value||'').toLowerCase();if(/(open|start).*trail mesh|trail mesh.*(open|start)/.test(q)){open('connect');return;}if(/mesh status|nearby network test/.test(q)){open('connect');return;}if(/find.*(lost|missing).*trekker|lost trekker/.test(q)){open('team');return;}if(/(mesh|nearby).*sos|sos.*(mesh|nearby)/.test(q)){open('sos');return;}return originalTusk.apply(this,arguments);};tusk.__rwm=true;window.copilotSend=tusk;}
  }

  window.RWTrailMesh = { isAvailable:function(){return Boolean(plugin());}, open:open, close:close, start:start, stop:stop, send:function(message,endpointId){return requirePlugin().sendMessage({message:message,endpointId:endpointId||null});}, sendChat:sendChat, status:function(){return requirePlugin().getStatus();} };
  window.RWNearbyMesh = window.RWTrailMesh;
  function boot(){if(!plugin())return;loadTrace();trace('ok','Boot','Native Trail Mesh bridge loaded');window.addEventListener('error',function(e){trace('error','UI',e.message||'Unknown JavaScript error');});window.addEventListener('unhandledrejection',function(e){trace('error','Promise',(e.reason&&e.reason.message)||String(e.reason||'Unhandled operation failure'));});installEntryPoints();installBridges();new MutationObserver(function(){installEntryPoints();installBridges();}).observe(document.body,{childList:true,subtree:true});}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
